mapper.select:
SELECT user_id, email, nickname, profile_image_path, role, email_verified, created_at, updated_at, deleted_at FROM users
ORDER BY
user_id email nickname updated_at user_id
${order.direction}
ORDER BY user_id DESC
LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT r.review_id, r.user_id, r.animation_id, a.title, r.content, r.rating, r.is_spoiler, r.like_count, r.report_count, r.is_hidden, r.created_at, r.updated_at FROM reviews r JOIN animations a ON r.animation_id = a.animation_id WHERE r.user_id = #{userId} AND r.deleted_at IS NULL
ORDER BY
r.review_id r.like_count r.updated_at r.review_id
${order.direction}
ORDER BY r.review_id DESC
LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT r.review_id, r.user_id, r.animation_id, a.title, r.content, r.rating, r.is_spoiler, r.like_count, r.report_count, r.is_hidden, r.created_at, r.updated_at FROM review_likes rl JOIN reviews r ON rl.review_id = r.review_id JOIN animations a ON r.animation_id = a.animation_id WHERE rl.user_id = #{userId} AND r.deleted_at IS NULL
ORDER BY
r.review_id r.like_count r.updated_at rl.review_like_id rl.review_like_id
${order.direction}
ORDER BY rl.review_like_id DESC
LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT a.animation_id, a.image_path AS thumbnail_image_path, a.title, ROUND(CASE WHEN a.review_count > 0 THEN a.rating_sum / a.review_count ELSE 0 END, 1) as rating FROM bookmarks b JOIN animations a ON b.animation_id = a.animation_id WHERE b.user_id = #{userId}
ORDER BY
ROUND(CASE WHEN a.review_count > 0 THEN a.rating_sum / a.review_count ELSE 0 END, 1)
b.bookmark_id b.bookmark_id
${order.direction}
ORDER BY b.bookmark_id DESC
LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT COUNT(*)
FROM bookmarks
WHERE user_id = #{userId}
